arguments.command:
/bin/bash -lc "for spec in 'capture_best|solver_examples/solver_649d7e789a5a/logs/evaluate/agent_observation/wake_diagnostics.json' 'capture_fast|solver_examples/solver_e6ed5ba2c4a4/logs/evaluate/agent_observation/wake_diagnostics.json' 'capture_repeat|solver_examples/solver_d2a3f8408b10/logs/evaluate/agent_observation/wake_diagnostics.json' 'failure_exact|guidance_examples/optimizer_e03fd65a925f/logs/step_31_worker_3_solver_ed281929e057/logs/evaluate/agent_observation/wake_diagnostics.json' 'capture_lag|guidance_examples/optimizer_656c64625b3e/logs/step_31_worker_1_solver_49732e0f6731/logs/evaluate/agent_observation/wake_diagnostics.json'; do
  name="'${spec%%|*}
  path=${spec#*|}
  jq -r '"'.trace[] | [.elapsed,.distance_L,.head[0],.head[1],.heading,.heading_rate_T,.velocity[0],.velocity[1],.joint[0],.joint[1],.joint[2],.joint[3],.force_body_coefficient[0],.force_body_coefficient[1],.moment_coefficient] | @tsv' \""'$path" |
  awk -v name="$name" '"'
  BEGIN { print \"trajectory=\" name; print \"t dist fwd_frac lat_frac heading yaw_rate closing speed q1 q2 moment\" }
  {
    bucket=int("'$1/2);
    if (!(bucket in seen)) {
      dx=9-$3; dy=9.5-$4; d=sqrt(dx*dx+dy*dy);
      fx=-cos($5); fy=-sin($5);
      lx=-sin($5); ly=cos($5);
      fwd=(dx*fx+dy*fy)/d; lat=(dx*lx+dy*ly)/d;
      speed=sqrt($7*$7+$8*$8);
      if (NR>1) closing=(prevd-$2)/($1-prevt); else closing=0;
      printf "%.2f %.3f %+.3f %+.3f %+.3f %+.3f %+.3f %.3f %+.3f %+.3f %+.4f'"\\n\","'$1,$2,fwd,lat,$5,$6,closing,speed,$9,$10,$15;
      seen[bucket]=1;
    }
    prevd=$2; prevt=$1
  }'"'
done"

/bin/bash -lc "for spec in 'capture_best|solver_examples/solver_649d7e789a5a/logs/evaluate/agent_observation/wake_diagnostics.json' 'capture_fast|solver_examples/solver_e6ed5ba2c4a4/logs/evaluate/agent_observation/wake_diagnostics.json' 'capture_repeat|solver_examples/solver_d2a3f8408b10/logs/evaluate/agent_observation/wake_diagnostics.json' 'failure_exact|guidance_examples/optimizer_e03fd65a925f/logs/step_31_worker_3_solver_ed281929e057/logs/evaluate/agent_observation/wake_diagnostics.json' 'capture_lag|guidance_examples/optimizer_656c64625b3e/logs/step_31_worker_1_solver_49732e0f6731/logs/evaluate/agent_observation/wake_diagnostics.json'; do
  name="'${spec%%|*}
  path=${spec#*|}
  jq -r '"'.trace[] | [.elapsed,.distance_L,.head[0],.head[1],.heading,.heading_rate_T,.velocity[0],.velocity[1],.joint[0],.joint[1],.moment_coefficient] | @tsv' \""'$path" |
  awk -v name="$name" '"'
  BEGIN { split(\"5 4 3 2.5 2 1.75 1.5 1.3\",th); print \"trajectory=\" name; print \"threshold t dist fwd lat yaw closing speed moment\" }
  {
    dx=9-"'$3; dy=9.5-$4; d=sqrt(dx*dx+dy*dy); fx=-cos($5); fy=-sin($5); lx=-sin($5); ly=cos($5);
    fwd=(dx*fx+dy*fy)/d; lat=(dx*lx+dy*ly)/d; speed=sqrt($7*$7+$8*$8);
    if(NR>1) closing=(prevd-$2)/($1-prevt); else closing=0;
    for(i=1;i<=8;i++) if(!hit[i] && $2<=th[i]) {printf "%.2f %.3f %.3f %+.3f %+.3f %+.3f %+.3f %.3f %+.4f'"\\n\",th[i],"'$1,$2,fwd,lat,$6,closing,speed,$11; hit[i]=1}
    prevd=$2; prevt=$1
  }'"'
done"

