 if($2<=5&&$2>3)b=1; else if($2<=3&&$2>2)b=2; else if($2<=2&&$2>1.3)b=3; else next;
 n[b]++; if(course<.85)c85[b]++;if(course<.8)c80[b]++;if(course<.75)c75[b]++;if(course<min[b]||!(b in min))min[b]=course;if(course>max[b]||!(b in max))max[b]=course;if(fwd>0&&course<.85)ahead85[b]++;
