 jq -r --argjson mt "$mint" '"'.trace[]|select(.elapsed <= "'$mt)|[.elapsed,.distance_L,.head[0],.head[1],.heading,.velocity[0],.velocity[1]]|@tsv'"' \""'$path" |
 awk -v name="$name" -v mt="$mint" '"'
 {
 dx=9-"'$3;dy=9.5-$4;d=sqrt(dx*dx+dy*dy);speed=sqrt($6*$6+$7*$7);if(speed<.1)next;fwd=(dx*(-cos($5))+dy*(-sin($5)))/d;course=(dx*$6+dy*$7)/(d*speed);
 if($2<=5&&$2>3)b=1;else if($2<=3&&$2>2)b=2;else if($2<=2&&$2>1.3)b=3;else next;n[b]++;if(course<.85)c85[b]++;if(course<.8)c80[b]++;if(course<.75)c75[b]++;if(!(b in min)||course<min[b])min[b]=course;if(!(b in max)||course>max[b])max[b]=course;if(fwd>0&&course<.85)ahead85[b]++;
